#[async_trait::async_trait]
impl<H: ServiceHandler + ?Sized> crate::Dispatch<H> for ServiceMessage {
    async fn dispatch(self, handler: &mut H) -> anyhow::Result<()> {
        match self {
            Self::CmdIsSensorAlive => handler.cmd_is_sensor_alive().await,
            Self::CmdDeleteTracks { key_id_list } => handler.cmd_delete_tracks(key_id_list).await,
            Self::CmdDeleteAllTracks => handler.cmd_delete_all_tracks().await,
            Self::CmdDeactivateSensor { deactivate } => handler.cmd_deactivate_sensor(deactivate).await,
            Self::ConfigSensorCoverage { key_id, coverage, is_removed } => handler.config_sensor_coverage(key_id, coverage, is_removed).await,
            Self::CmdSetPreset { preset } => handler.cmd_set_preset(preset).await,
            Self::CmdLockOnTracks { key_id_list } => handler.cmd_lock_on_tracks(key_id_list).await,
            Self::CmdMultiFireLaser { is_activated } => handler.cmd_multi_fire_laser(is_activated).await,
            Self::CmdSingleFireLaser => handler.cmd_single_fire_laser().await,
            Self::ConfigSetFirstOrLastMeasurement { strongest_measurement } => handler.config_set_first_or_last_measurement(strongest_measurement).await,
            Self::ConfigSetUserRange { minimum_range, maximum_range } => handler.config_set_user_range(minimum_range, maximum_range).await,
            Self::ConfigInhibitLaserFiring { key_component_id, is_removed } => handler.config_inhibit_laser_firing(key_component_id, is_removed).await,
            Self::ConfigMultiFireFrequency { frequency } => handler.config_multi_fire_frequency(frequency).await,
        }
    }
}

/// Laser Range Finder (LRF) Client interface.
/// Contains operations reported by a Laser Range Finder Service.
///
/// Operations of `M_LaserRangeFinder::IClient`, one variant per operation.
/// Includes the operations inherited from `M_Sensor::IClient`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema, strum::IntoStaticStr)]
pub enum ClientMessage {
    /// Report static settings of the sensor.
    ReportSensorSettings {
        /// Sensor settings data.
        #[serde(rename = "Settings")]
        settings: crate::sensor::SensorSettingsType,
    },
    /// Report current status of the sensor.
    ReportSensorStatus {
        /// Current status data for sensor.
        #[serde(rename = "Status")]
        status: crate::sensor::SensorStatusType,
        /// Indicates if the status is no longer available.
        /// Note: This will always be set to True when a Service has been shut down.
        /// After this has been set to True the status will no longer be available to late joiners.
        #[serde(rename = "IsRemoved")]
        is_removed: bool,
    },
    /// Report current coverage of the sensor.
    ReportSensorCoverage {
        /// The unique ID of the coverage.
        #[serde(rename = "KeyId")]
        key_id: crate::common::ObjectIdType,
        /// Sensor coverage.
        #[serde(rename = "Coverage")]
        coverage: crate::sensor::SensorCoverageType,
        /// Indicates if the coverage is no longer available.
        /// Note: This will always be set to True when a Service has been shut down.
        /// After this has been set to True the status will no longer be available to late joiners.
        #[serde(rename = "IsRemoved")]
        is_removed: bool,
    },
    /// Event of a detected object.
    EventSensorDetection {
        /// Identifies the detection for the location measurement.
        /// Note: Since an event does not have a lifetime, it cannot be updated/deleted, but
        /// multiple locations can belong to the same detection and will then have
        /// the same detection ID.
        #[serde(rename = "DetectionId")]
        detection_id: crate::common::ObjectIdType,
        /// Detection data.
        #[serde(rename = "Detection")]
        detection: crate::sensor::SensorDetectionType,
    },
    /// Report an object tracked by the sensor (i.e. a track).
    /// A tracked object has a lifetime and updates to the same tracked object will be
    /// reported with the same KeyId. When an object is no longer tracked (i.e. lost), it
    /// should be reported with IsRemoved set to true.
    ///
    /// Note: If the sensor does NOT have the ability to track objects then a detection
    /// should be reported via the EventSensorDetection() operation instead.
    ReportSensorTrack {
        /// The unique track ID.
        #[serde(rename = "KeyId")]
        key_id: crate::common::ObjectIdType,
        /// Tracked object data.
        #[serde(rename = "Track")]
        track: crate::sensor::SensorDetectionType,
        /// Indicates if the sensor track has been lost (i.e. no longer tracked by sensor).
        /// Note: After this has been set to True the track will no longer be available to late joiners.
        #[serde(rename = "IsRemoved")]
        is_removed: bool,
    },
    /// Contains the static settings for a Laser Range Finder (LRF).
    /// This should be provided at startup and in the event of degraded functionality,
    /// e.g. due to an internal failure.
    ReportLrfSettings {
        /// Laser Range Finder settings data.
        #[serde(rename = "Settings")]
        settings: LrfSettingsType,
    },
    /// Report status of Laser Range Finder.
    ReportLrfStatus {
        /// Current status data for Laser Range Finder (LRF).
        #[serde(rename = "Status")]
        status: LrfStatusType,
        /// Indicates if the status is no longer available.
        /// Note: This will always be set to true when a service has been shut down.
        /// After this has been set to true, the status will no longer be available to late joiners.
        #[serde(rename = "IsRemoved")]
        is_removed: bool,
    },
}

impl crate::Message for ClientMessage {
    const INTERFACE: &'static str = "M_LaserRangeFinder::IClient";

    fn op_id(&self) -> u32 {
        match self {
            Self::ReportSensorSettings { .. } => 0,
            Self::ReportSensorStatus { .. } => 1,
            Self::ReportSensorCoverage { .. } => 2,
            Self::EventSensorDetection { .. } => 3,
            Self::ReportSensorTrack { .. } => 4,
            Self::ReportLrfSettings { .. } => 5,
            Self::ReportLrfStatus { .. } => 6,
        }
    }

    fn op_name(&self) -> &'static str {
        self.into()
    }

    fn encode_args(&self, w: &mut Writer) {
        #[allow(unused_variables)]
        match self {
            Self::ReportSensorSettings { settings } => {
                settings.encode(w);
            }
            Self::ReportSensorStatus { status, is_removed } => {
                status.encode(w);
                is_removed.encode(w);
            }
            Self::ReportSensorCoverage { key_id, coverage, is_removed } => {
                key_id.encode(w);
                coverage.encode(w);
                is_removed.encode(w);
            }
            Self::EventSensorDetection { detection_id, detection } => {
                detection_id.encode(w);
                detection.encode(w);
            }
            Self::ReportSensorTrack { key_id, track, is_removed } => {
                key_id.encode(w);
                track.encode(w);
                is_removed.encode(w);
            }
            Self::ReportLrfSettings { settings } => {
                settings.encode(w);
            }
            Self::ReportLrfStatus { status, is_removed } => {
                status.encode(w);
                is_removed.encode(w);
            }
        }
    }

    fn decode(op: u32, r: &mut Reader<'_>) -> Result<Self, WireError> {
        Ok(match op {
            0 => Self::ReportSensorSettings {
                settings: Decode::decode(r)?,
            },
            1 => Self::ReportSensorStatus {
                status: Decode::decode(r)?,
                is_removed: Decode::decode(r)?,
            },
            2 => Self::ReportSensorCoverage {
                key_id: Decode::decode(r)?,
                coverage: Decode::decode(r)?,
                is_removed: Decode::decode(r)?,
            },
            3 => Self::EventSensorDetection {
                detection_id: Decode::decode(r)?,
                detection: Decode::decode(r)?,
            },
            4 => Self::ReportSensorTrack {
                key_id: Decode::decode(r)?,
                track: Decode::decode(r)?,
                is_removed: Decode::decode(r)?,
            },
            5 => Self::ReportLrfSettings {
                settings: Decode::decode(r)?,
            },
            6 => Self::ReportLrfStatus {
                status: Decode::decode(r)?,
                is_removed: Decode::decode(r)?,
            },
            _ => return Err(WireError::UnknownOp { interface: "M_LaserRangeFinder::IClient", op }),
        })
    }
}

